from decimal import Decimal


def line_total(lines):
    x = 0
    for line in lines:
        x += line["quantity"] * line["unit_cents"]
    return x


def tax_for(amount_cents, rate):
    """Tax in integer cents on amount_cents; rate is a decimal fraction (0.0825)."""
    if not isinstance(rate, Decimal):
        rate = Decimal(str(rate))
    tax = Decimal(amount_cents) * rate
    return int(tax.quantize(Decimal(1), rounding=ROUND_HALF_EVEN))
